import {SleepRecorder} from './recording.js';
import {storeClip,listClips,getClip,deleteClip,putSession,getSession,listSessions,deleteSession} from './storage.js';
import {formatDuration as fmt,dateKey,clockTime,displayTime,durationBetween,nextAlarm,rhythmStats,habitComparisons,escapeHTML as safe} from './core.js';

const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const screen=$('#screen'),sheet=$('#sheet'),body=$('#sheet-body');
function load(k,d){try{return JSON.parse(localStorage.getItem('studio-'+k))??d}catch{return d}}
function save(k,v){try{localStorage.setItem('studio-'+k,JSON.stringify(v));return true}catch{toast('Device storage is full or unavailable. Export your journal before closing.');return false}}
let entries=load('entries',null);
if(!Array.isArray(entries)){try{entries=JSON.parse(localStorage.getItem('ios-entries')||'[]')}catch{entries=[]}entries=entries.map(e=>({...e,id:e.id||crypto.randomUUID()}));save('entries',entries)}
let prefs={wake:'07:00',goal:8,record:false,threshold:.035,alarm:true,snooze:5,volume:.3,soundTimer:30,keepAwake:true,energy:'saver',clipLimit:100,...load('prefs',{})};
let session=load('session',null),tab='sleep',range=7,selectedEntry=null,clips=[],recStatus='idle',recError='',level=0,clipCount=0,recorder=null,wakeLock=null,alarmAudio=null,alarmDue=session?.alarmDue||null,ringing=false;
let sessionTimer=null,finishing=false,captureToken=0,clipPlayToken=0,isEventRecording=false;
let sound='',soundAudio=null,soundTimer=null,clipURL=null,deferredInstall=null,refresh=0;
const sounds=[['rain','☂','Soft rainfall','A gentle hush for a busy mind'],['ocean','≈','Ocean at dusk','Slow waves. Nothing to rush.'],['warm','☁','Warm noise','A soft, steady blanket of sound'],['hum','☾','Night hum','Low tones, a quieter evening'],['forest','♧','Evening forest','A softly rustling canopy'],['fire','♨','By the fireside','Warm embers and gentle crackles'],['stream','≋','Mountain stream','A little water, a little quiet'],['breath','◯','A slower breath','A soft six-second breathing rhythm']];
const brand='<svg viewBox="0 0 24 24"><circle cx="12" cy="13" r="8"/><path d="m8 2-4 3m12-3 4 3m-8 3v6l4 2"/></svg> Sleep Studio';
const persistPrefs=()=>save('prefs',prefs),persistEntries=()=>save('entries',entries);
const installed=()=>matchMedia('(display-mode: standalone)').matches||navigator.standalone===true;
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),3500)}
function head(title,sub,action=''){return `<div class="topline"><span class="kicker">SLEEP STUDIO</span>${action||'<span class="tag">ON YOUR DEVICE</span>'}</div><h1 class="heading">${title}</h1><p class="subtitle">${sub}</p>`}
function go(next){tab=next;stopClipPlayback();$$('[data-tab]').forEach(b=>{b.classList.toggle('active',b.dataset.tab===tab);b.setAttribute('aria-current',b.dataset.tab===tab?'page':'false')});({sleep:renderSleep,journal:renderJournal,trends:renderTrends,profile:renderProfile}[tab])();screen.scrollTop=0}
$$('[data-tab]').forEach(b=>b.onclick=()=>go(b.dataset.tab));
function positionSheet(){const r=$('.iphone').getBoundingClientRect(),edge=innerWidth>700&&!installed()?9:0;Object.assign(sheet.style,{position:'fixed',left:(r.left+edge)+'px',right:'auto',bottom:Math.max(0,innerHeight-r.bottom+edge)+'px',width:(r.width-edge*2)+'px',maxHeight:Math.max(200,r.height-45)+'px'})}
function modal(html){body.innerHTML=html;if(!sheet.open)sheet.showModal();positionSheet();body.scrollTop=0}
function sh(title){return `<div class="sheet-top"><h2 id="sheet-title">${title}</h2><button class="sheet-close" aria-label="Close sheet">×</button></div>`}
document.addEventListener('click',e=>{if(e.target.closest('.sheet-close'))sheet.close()});
sheet.addEventListener('close',stopClipPlayback);
sheet.addEventListener('click',e=>{if(e.target===sheet){const r=sheet.getBoundingClientRect();if(e.clientY<r.top||e.clientX<r.left||e.clientX>r.right)sheet.close()}});
window.addEventListener('resize',()=>{if(sheet.open)positionSheet()});

function renderSleep(){
  if(session){renderSession();return}
  const [t,p]=displayTime(prefs.wake),greeting=new Date().getHours()<12?'Good morning.':new Date().getHours()<18?'A little space for rest.':'Good evening.';
  screen.innerHTML=`<div class="topline"><div class="brand">${brand}</div><button class="circle-button" id="settings" aria-label="Sleep preferences">⚙</button></div><div class="greeting"><span>☾</span> ${greeting}</div><h1 class="wake-heading">Let the day drift away.</h1><p class="subtitle">Your nights. A little more understood.</p><div class="next">${prefs.alarm?'Your next wake-up':'Sleep without an alarm'}</div><button class="clock" id="wake" aria-label="Change wake-up time"><svg viewBox="0 0 270 270"><defs><linearGradient id="orange-ring"><stop stop-color="#ffcc99"/><stop offset="1" stop-color="#ff9955"/></linearGradient></defs><circle cx="135" cy="135" r="130" fill="none" stroke="#304951" stroke-width="3"/><circle cx="135" cy="135" r="130" fill="none" stroke="url(#orange-ring)" stroke-width="3" stroke-dasharray="646 817" stroke-linecap="round"/></svg><div class="ticks"></div><span class="sun">${prefs.alarm?'☀':'☾'}</span><span class="kicker">${prefs.alarm?'WAKE-UP TIME':'TIME TO UNWIND'}</span><span class="clock-time">${prefs.alarm?t:'Rest'}<small>${prefs.alarm?p:''}</small></span><span class="clock-edit">Tap to adjust</span></button><p class="goal-line">Your space to rest · <strong>${prefs.goal} hour goal</strong></p><button class="row" id="sounds"><span class="row-icon">≈</span><span><strong>${sound?sounds.find(s=>s[0]===sound)[2]:'Find your quiet'}</strong><small>${sound?'Playing · tap to open sound player':'Eight offline wind-down sounds'}</small></span><span class="play">${sound?'Ⅱ':'▶'}</span></button><button class="row compact" id="record-options"><span class="row-icon">♬</span><span><strong>Night-sound recording</strong><small>${prefs.record?'On · event clips stored on this device':'Off · tap to choose before sleeping'}</small></span><span class="toggle ${prefs.record?'on':''}" aria-hidden="true"></span></button><button class="primary" id="start">☾ &nbsp; Start sleep session</button><p class="note">${prefs.record?'Microphone permission requested when you start.':'A private journal. No microphone unless you choose.'}</p>${!installed()?'<button class="install-link" id="install">＋ Add Sleep Studio to Home Screen</button>':''}`;
  $('#settings').onclick=()=>go('profile');$('#wake').onclick=wakeSheet;$('#sounds').onclick=soundsSheet;$('#record-options').onclick=recordSheet;$('#start').onclick=startSheet;if($('#install'))$('#install').onclick=installSheet;
}
function wakeSheet(){
  modal(sh('Your morning, your time.')+`<label class="setting">Wake-up alarm <input id="alarm-enabled" type="checkbox" ${prefs.alarm?'checked':''}></label><label for="wake-time">Wake-up time</label><input class="sheet-time" id="wake-time" type="time" value="${prefs.wake}"><label for="snooze">Snooze</label><select id="snooze">${[1,5,10,15].map(n=>`<option value="${n}" ${n===prefs.snooze?'selected':''}>${n} minutes</option>`).join('')}</select><button class="secondary" id="alarm-preview">Preview wake-up chime</button><button class="primary" id="save-wake">Save wake-up time</button><p class="sheet-copy">Keep this app open and your device awake for the alarm. iOS may pause web apps in the background or with the screen locked. Use your iPhone Clock alarm as a backup.</p>`);
  $('#alarm-preview').onclick=()=>playAlarm(true);$('#save-wake').onclick=()=>{if(!$('#wake-time').value)return;prefs.wake=$('#wake-time').value;prefs.alarm=$('#alarm-enabled').checked;prefs.snooze=Number($('#snooze').value);persistPrefs();sheet.close();go(tab);toast('Wake-up preferences saved.')};
}
function recordSheet(){
  modal(sh('Listen back to your night.')+`<p class="sheet-copy">Save short audio clips when sound rises above your chosen level. Listen back in your journal. Clips stay in this browser’s device storage and are never uploaded.</p><label class="setting">Record night-sound events <input id="record-enabled" type="checkbox" ${prefs.record?'checked':''}></label><label for="sensitivity">Sound sensitivity</label><input id="sensitivity" type="range" min="10" max="100" value="${Math.round((.11-prefs.threshold)*1000)}"><p class="note">Higher sensitivity captures quieter sounds. Sound events are not automatically classified as snoring or sleep talking.</p><button class="primary" id="save-record">Save recording preference</button><p class="sheet-copy">Keep the app visible and the screen awake. Calls, switching apps, locking the screen, or iOS interruptions can stop recording. Gaps are shown in your night summary. Recording other people requires their agreement.</p>`);
  $('#save-record').onclick=()=>{prefs.record=$('#record-enabled').checked;prefs.threshold=Math.max(.01,.11-Number($('#sensitivity').value)/1000);persistPrefs();sheet.close();go(tab);toast(prefs.record?'Recording enabled for your next session.':'Recording is off.')};
}
function startSheet(){
  modal(sh('Ready to turn in?')+`<div class="ready-summary"><div>Wake-up <strong>${prefs.alarm?displayTime(prefs.wake).join(' '):'No alarm'}</strong></div><div>Sound clips <strong>${prefs.record?'Microphone on':'Off'}</strong></div><div>Sleep goal <strong>${prefs.goal} hours</strong></div></div><label class="setting">Keep screen awake <input id="keep-awake" type="checkbox" ${prefs.keepAwake?'checked':''}></label><p class="sheet-copy">${prefs.record?'You’ll be asked for microphone access. Only short sound-event clips are saved on this device.':'Your session records elapsed time in bed. You can add a reflection in the morning.'}</p><p class="note">Web apps cannot guarantee overnight recording or alarm delivery while locked or backgrounded. Plug in your phone and set a backup alarm in Clock.</p><button class="primary" id="begin">${prefs.record?'Start & allow microphone':'Start my night'}</button>`);
  $('#begin').onclick=async()=>{const b=$('#begin');b.disabled=true;b.textContent='Starting…';prefs.keepAwake=$('#keep-awake').checked;persistPrefs();await beginSession();sheet.close();renderSession()};
}
async function beginSession(){
  session={id:crypto.randomUUID(),startedAt:Date.now(),recordingRequested:prefs.record,alarmDue:prefs.alarm?nextAlarm(prefs.wake):null,gaps:[]};alarmDue=session.alarmDue;save('session',session);startSessionTicker();clipCount=0;recError='';
  try{await putSession({id:session.id,startedAt:session.startedAt,status:'active',gaps:[]})}catch(e){toast('Recording storage unavailable. Your session timer will still work.')}
  if(prefs.keepAwake)await requestWakeLock();
  if(prefs.record)await startRecorder();
}
async function startRecorder(){
  if(!session||finishing)return;
  const expected=session.id,token=++captureToken;
  recError='';recStatus='starting';
  if(!recorder)recorder=new SleepRecorder({
    onStatus:status=>{recStatus=typeof status==='string'?status:(status.state||status.status||'monitoring');if(Number.isFinite(status.clips))clipCount=status.clips;if(['clip-limit','size-limit','storage-or-recorder-error'].includes(status.reason))recError='Recording stopped at its storage or clip limit. Download clips before continuing.';updateRecordingUI()},
    onLevel:value=>{level=typeof value==='number'?value:(value.rms||value.level||0);isEventRecording=!!value.recording;const meter=$('#sound-meter');if(meter)meter.style.width=Math.min(100,level*1000)+'%';updateRecordingUI()},
    onClip:()=>{clipCount++;const count=$('#clip-count');if(count)count.textContent=String(clipCount)},
    onError:error=>{recError=error.message||String(error);recStatus='error';updateRecordingUI()}
  });
  try{await recorder.start({sessionId:expected,threshold:prefs.threshold,maxClips:prefs.clipLimit,sampleIntervalMs:prefs.energy==='saver'?500:200,fftSize:1024,audioBitsPerSecond:prefs.energy==='saver'?24000:32000});if(finishing||!session||session.id!==expected||token!==captureToken){await recorder.stop({reason:'stale-session'});return}recStatus=recorder.state}catch(e){recError=e.message||String(e);recStatus='error'}
  updateRecordingUI();
}
function updateRecordingUI(){const dot=$('.mic-dot');if(dot)dot.classList.toggle('live',['monitoring','listening'].includes(recStatus));const count=$('#clip-count');if(count)count.textContent=String(clipCount);const status=$('#recording-state');if(status)status.textContent=recordingLabel();const error=$('#recording-error');if(error){error.textContent=recError;error.hidden=!recError}const resume=$('#resume-recording');if(resume)resume.hidden=['listening','recording','starting','requesting','monitoring'].includes(recStatus)}
function recordingLabel(){if(recError)return 'Recording needs attention';if(isEventRecording||['recording','capturing'].includes(recStatus))return 'Saving a sound event';if(['listening','monitoring'].includes(recStatus))return 'Listening for sound events';if(['starting','requesting'].includes(recStatus))return 'Starting microphone…';return session?.recordingRequested?'Recording paused · tap Resume':'Microphone is off'}
async function requestWakeLock(){try{if('wakeLock'in navigator){wakeLock=await navigator.wakeLock.request('screen');wakeLock.addEventListener('release',()=>{wakeLock=null;const n=$('#wake-status');if(n)n.textContent='Screen wake lock released. Keep the app visible.'})}}catch{wakeLock=null}}
function elapsed(){if(!session)return '00:00:00';const n=Math.max(0,Math.floor((Date.now()-session.startedAt)/1000));return [Math.floor(n/3600),Math.floor(n/60)%60,n%60].map(n=>String(n).padStart(2,'0')).join(':')}
function renderSession(){
  if(!session){renderSleep();return}
  if(finishing){screen.innerHTML=head('Saving your night…','Finalizing the last clip and your journal.');return}
  screen.innerHTML=`<div class="topline"><div class="brand">☾ Sleep Studio</div><span class="tag">SESSION ACTIVE</span></div><div class="session"><span class="moon">☾</span><h1 class="wake-heading">Sleep well.</h1><p>Nothing left to do.<br>Just a little space for rest.</p><div class="elapsed" id="elapsed">${elapsed()}</div><span class="kicker">TIME IN BED</span><p>${prefs.alarm?'Wake-up planned for '+displayTime(prefs.wake).join(' '):'No wake-up alarm set'}</p></div><div class="recording-card"><div class="recording-title"><span class="mic-dot ${['monitoring','listening'].includes(recStatus)?'live':''}"></span><strong id="recording-state">${recordingLabel()}</strong></div><div class="meter"><i id="sound-meter"></i></div><p><span id="clip-count">${clipCount}</span> clips saved on this device</p><p class="error-copy" id="recording-error" ${recError?'':'hidden'}>${safe(recError)}</p>${session.recordingRequested?'<button class="secondary" id="resume-recording">Resume microphone recording</button><button class="secondary" id="pause-recording">Pause recording</button>':''}<small id="wake-status">${wakeLock?'Screen stays awake while this app is visible.':'Keep this app visible. The screen may lock.'}</small></div><button class="row compact" id="session-sounds"><span class="row-icon">≈</span><span><strong>${sound?'Wind-down sound is playing':'Find your quiet'}</strong><small>Open sound player</small></span><span class="play">▶</span></button><button class="primary" id="end">End session & save night</button><button class="secondary" id="dim">${document.body.classList.contains('night-mode')?'Restore brightness':'Dim the screen'}</button><button class="secondary subtle" id="discard">Discard this session</button><p class="note">Elapsed time is time in bed, not measured time asleep.<br>Keep a backup alarm in your iPhone Clock app.</p>`;
  $('#session-sounds').onclick=soundsSheet;$('#end').onclick=async()=>{const b=$('#end');b.disabled=true;b.textContent='Saving your night…';await finishSession(true)};$('#discard').onclick=()=>{modal(sh('Discard this night?')+'<p class="sheet-copy">This removes this session and its recorded clips from the device.</p><button class="primary" id="confirm-discard">Discard session and clips</button><button class="secondary sheet-close">Keep recording</button>');$('#confirm-discard').onclick=async()=>{await finishSession(false);sheet.close()}};$('#dim').onclick=()=>{document.body.classList.toggle('night-mode');$('#dim').textContent=document.body.classList.contains('night-mode')?'Restore brightness':'Dim the screen'};
  if($('#resume-recording'))$('#resume-recording').onclick=async()=>{if(finishing)return;const button=$('#resume-recording');if(button)button.disabled=true;if(recorder?.state==='interrupted'&&await recorder.resume()){recError='';recStatus=recorder.state}else{if(recorder)await recorder.stop({reason:'user-pause'});await startRecorder()}if(prefs.keepAwake)await requestWakeLock();if(session&&!finishing)renderSession()};
  if($('#pause-recording'))$('#pause-recording').onclick=async()=>{if(finishing)return;if(recorder)await recorder.stop({reason:'user-pause'});recStatus='paused';isEventRecording=false;if(session&&!finishing)renderSession()};updateRecordingUI();
}
async function finishSession(keep){
  if(!session||finishing)return;finishing=true;++captureToken;
  const current=session,end=Date.now();
  try{
    try{if(recorder)await recorder.stop()}catch(e){toast('Some recording data could not be finalized.')}
    if(keep){
      let records=[];
      try{const metadata=await getSession(current.id);await putSession({...metadata,id:current.id,startedAt:current.startedAt,endedAt:end,status:'complete',gaps:[...(metadata?.gaps||[]),...(current.gaps||[])]});records=await listClips(current.id)}catch(e){toast('Audio storage needs attention. Your journal will keep a link to any saved clips.')}
      const a=new Date(current.startedAt),b=new Date(end);
      const entry={id:current.id,sessionId:current.id,date:dateKey(a),bed:clockTime(a),wake:clockTime(b),startedAt:current.startedAt,endedAt:end,minutes:Math.round((end-current.startedAt)/60000),mood:'Not recorded',note:'',factors:[],clipCount:records.length};
      entries=[entry,...entries.filter(e=>e.id!==current.id)];
      if(!persistEntries()){recError='Journal storage is full. Your session is retained. Export your journal in Profile, free space, then save again.';recStatus='stopped';finishing=false;renderSession();return}
    }else{try{await deleteSession(current.id)}catch(e){toast('Audio could not be removed. The session is retained for another attempt.');finishing=false;renderSession();return}}
    session=null;save('session',null);clearInterval(sessionTimer);sessionTimer=null;alarmDue=null;ringing=false;stopAlarm();stopSound();if(wakeLock){await wakeLock.release().catch(()=>{});wakeLock=null}document.body.classList.remove('night-mode');recStatus='idle';isEventRecording=false;
    if(keep){selectedEntry=current.id;go('journal');toast('Night saved. Listen to your clips or add a reflection.')}else go('sleep');
  }finally{finishing=false}
}

async function renderJournal(){
  const token=++refresh;selectedEntry=entries.some(e=>e.id===selectedEntry)?selectedEntry:entries[0]?.id;const e=entries.find(e=>e.id===selectedEntry);
  screen.innerHTML=head('Your journal.','Your nights, in your own words.','<button class="circle-button" id="add" aria-label="Add a night">+</button>')+(!e?`<div class="empty"><span>☾</span><h3>Your first night awaits.</h3><p>Start a session to capture sound events, or add a night manually.</p><button class="primary" id="first-night">Add a night</button></div>`:`<label for="night-select">Choose a night</label><select id="night-select">${entries.map(n=>`<option value="${safe(n.id)}" ${n.id===e.id?'selected':''}>${safe(n.date)} · ${fmt(n.minutes)}</option>`).join('')}</select><div class="stats"><div class="quality" style="--quality:${Math.min(100,e.minutes/(prefs.goal*60)*100)}%"><div><strong>${Math.round(e.minutes/(prefs.goal*60)*100)}<small>%</small></strong><span>Time-in-bed goal</span></div></div><div class="duration"><strong>${fmt(e.minutes)}</strong><span>Time in bed</span><strong>${safe(e.bed)} – ${safe(e.wake)}</strong><span>Bedtime & wake-up</span></div></div><div class="section"><span>Sounds from your night</span><span class="tag">ON THIS DEVICE</span></div><div id="night-clips"><p class="subtitle">Loading your recordings…</p></div><button class="secondary" id="import-recording">＋ Import an audio recording</button><div class="reflection"><div class="reflection-head"><strong>☀ Your morning reflection</strong><button id="reflect">Edit</button></div><p>${safe(e.note)||'How did your night feel? Add a little reflection.'}</p><div class="factor-tags">${[e.mood,...(e.factors||[])].filter(v=>v&&v!=='Not recorded').map(f=>`<span>${safe(f)}</span>`).join('')}</div></div><button class="secondary subtle" id="remove-night">Delete this night</button>`);
  $('#add').onclick=()=>nightForm();if($('#first-night'))$('#first-night').onclick=()=>nightForm();if(!e)return;
  $('#night-select').onchange=()=>{selectedEntry=$('#night-select').value;stopClipPlayback();renderJournal()};$('#reflect').onclick=()=>nightForm(e);$('#remove-night').onclick=()=>confirmDeleteNight(e);$('#import-recording').onclick=()=>importRecording(e);
  try{const records=e.sessionId?await listClips(e.sessionId):[];if(token!==refresh||tab!=='journal')return;clips=records;$('#night-clips').innerHTML=records.length?`<div class="sound-activity" aria-label="Sound events through your night">${records.map(c=>`<i style="--event:${Math.max(15,Math.min(100,(c.level||c.peakLevel||.04)*1000))}%"></i>`).join('')}</div><p class="note">Sound activity · not sleep stages or a snoring diagnosis</p>${records.map(c=>`<article class="clip"><div><strong>${new Date(c.startedAt||c.createdAt||Date.now()).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'})}</strong><small>${Math.round((c.durationMs||0)/1000)} sec · ${safe(c.userLabel|| (c.imported?'Imported audio':'Sound event'))}</small></div><button class="clip-play" data-play="${safe(c.id)}" aria-label="Play sound clip">▶</button><button data-label="${safe(c.id)}" aria-label="Label sound clip">✎</button><button data-download="${safe(c.id)}" aria-label="Download sound clip">↓</button><button data-delete-clip="${safe(c.id)}" aria-label="Delete sound clip">×</button></article>`).join('')}<audio id="clip-player" controls preload="none" class="recording-player" hidden></audio>`:`<div class="empty-recordings"><span>♬</span><p>${e.sessionId?'No sound clips saved for this night. Microphone recording may have been off, interrupted, or no events crossed the threshold.':'This night was added manually. Start a microphone-enabled session to capture sound clips.'}</p></div>`;
    const meta=e.sessionId?await getSession(e.sessionId):null;if(token!==refresh||tab!=='journal')return;if(meta?.gaps?.length){const observed=meta.gaps.filter(g=>g.kind!=='potential').length,potential=meta.gaps.length-observed;$('#night-clips').insertAdjacentHTML('beforeend',`<p class="gap-notice">${observed?observed+' recording interruption'+(observed===1?'':'s')+' logged. ':''}${potential?potential+' background period'+(potential===1?'':'s')+' may have affected capture. ':''}Review audio coverage before drawing conclusions.</p>`)}
    $$('[data-label]').forEach(b=>b.onclick=()=>labelClip(b.dataset.label));$$('[data-play]').forEach(b=>b.onclick=()=>playClip(b.dataset.play));$$('[data-download]').forEach(b=>b.onclick=()=>downloadClip(b.dataset.download));$$('[data-delete-clip]').forEach(b=>b.onclick=()=>{modal(sh('Remove this sound clip?')+'<p class="sheet-copy">This audio clip will be deleted from this device.</p><button class="primary" id="delete-clip">Delete clip</button>');$('#delete-clip').onclick=async()=>{stopClipPlayback();await deleteClip(b.dataset.deleteClip);sheet.close();renderJournal()}});
  }catch(error){if($('#night-clips'))$('#night-clips').innerHTML='<p class="gap-notice">Recording storage is unavailable. Your text journal is still saved.</p>'}
}
function nightForm(existing=null){
  modal(sh(existing?'Your morning reflection.':'A night to remember.')+`<form id="night-form"><label for="date">Night of</label><input id="date" type="date" value="${existing?.date||dateKey()}" required><div class="form-row"><div><label for="bed">Bedtime</label><input id="bed" type="time" value="${existing?.bed||'23:00'}" required ${existing?.sessionId?'disabled':''}></div><div><label for="end-time">Wake-up time</label><input id="end-time" type="time" value="${existing?.wake||prefs.wake}" required ${existing?.sessionId?'disabled':''}></div></div>${existing?.sessionId?'<p class="note">Duration comes from your timed session.</p>':''}<label for="mood">How did you feel?</label><select id="mood">${['Rested','Okay','Tired','Not recorded'].map(m=>`<option ${existing?.mood===m?'selected':''}>${m}</option>`).join('')}</select><label>What shaped your night?</label><div class="factor-picker">${['Exercise','Caffeine','Alcohol','Stress','Late screen','Travel'].map(f=>`<label><input type="checkbox" name="factor" value="${f}" ${(existing?.factors||[]).includes(f)?'checked':''}>${f}</label>`).join('')}</div><label for="reflection">A little reflection</label><textarea id="reflection" maxlength="500" placeholder="What helped you rest?">${safe(existing?.note||'')}</textarea><button class="primary">Save my night</button></form>`);
  $('#night-form').onsubmit=event=>{event.preventDefault();try{const minutes=existing?.sessionId?existing.minutes:durationBetween($('#bed').value,$('#end-time').value);const entry={...existing,id:existing?.id||crypto.randomUUID(),date:$('#date').value,bed:$('#bed').value,wake:$('#end-time').value,minutes,mood:$('#mood').value,note:$('#reflection').value.trim(),factors:$$('input[name=factor]:checked').map(i=>i.value)};if(existing)entries=entries.map(e=>e.id===entry.id?entry:e);else entries.unshift(entry);persistEntries();selectedEntry=entry.id;sheet.close();go('journal');toast('Your night is saved.')}catch(error){toast(error.message)}};
}
function confirmDeleteNight(e){modal(sh('Remove this night?')+'<p class="sheet-copy">The journal entry and its recordings will be removed from this device.</p><button class="primary" id="delete-night">Delete night and clips</button><button class="secondary sheet-close">Keep it</button>');$('#delete-night').onclick=async()=>{if(e.sessionId)await deleteSession(e.sessionId);entries=entries.filter(n=>n.id!==e.id);persistEntries();sheet.close();renderJournal();toast('Night removed.')}}
async function playClip(id){try{stopSound();stopClipPlayback();const token=clipPlayToken,clip=await getClip(id);if(token!==clipPlayToken||!$('#clip-player'))return;if(!clip?.blob)throw new Error('Clip unavailable.');clipURL=URL.createObjectURL(clip.blob);const player=$('#clip-player');player.hidden=false;player.src=clipURL;player.playbackRate=1;await player.play()}catch(e){toast('This recording could not be played in this browser. Try downloading it.')}}
function stopClipPlayback(){++clipPlayToken;const p=$('#clip-player');if(p){p.pause();p.removeAttribute('src');p.load()}if(clipURL){URL.revokeObjectURL(clipURL);clipURL=null}}
async function downloadClip(id){const c=await getClip(id);if(c?.blob){const type=c.blob.type,ext=type.includes('mp4')?'m4a':type.includes('wav')?'wav':type.includes('mpeg')?'mp3':type.includes('ogg')?'ogg':'webm';download(c.blob,`sleep-studio-${new Date(c.startedAt||Date.now()).toISOString().replace(/[:.]/g,'-')}.${ext}`)}}
function audioDuration(file){return new Promise(resolve=>{const url=URL.createObjectURL(file),audio=new Audio();let settled=false;const done=value=>{if(settled)return;settled=true;clearTimeout(timer);audio.onloadedmetadata=null;audio.onerror=null;audio.removeAttribute('src');audio.load();URL.revokeObjectURL(url);resolve(value)};const timer=setTimeout(()=>done(0),2500);audio.preload='metadata';audio.onloadedmetadata=()=>done(Number.isFinite(audio.duration)?Math.round(audio.duration*1000):0);audio.onerror=()=>done(0);audio.src=url})}

function download(blob,name){const u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),30000)}
function importRecording(entry){
  modal(sh('Add an audio recording.')+'<p class="sheet-copy">Choose an audio file from this device. It will be copied into your private local journal. Maximum 20 MB.</p><label for="audio-import">Audio file</label><input type="file" id="audio-import" accept="audio/*"><button class="primary" id="save-import">Save recording</button>');
  $('#save-import').onclick=async()=>{const file=$('#audio-import').files[0];if(!file){toast('Choose an audio file first.');return}if(file.size>20*1024*1024||(!file.type.startsWith('audio/')&&!/\.(m4a|mp4|wav|mp3|webm|ogg)$/i.test(file.name))){toast('Choose an audio file smaller than 20 MB.');return}try{const sessionId=entry.sessionId||entry.id;await putSession({...(await getSession(sessionId)),id:sessionId,startedAt:entry.startedAt||Date.now(),status:'complete'});await storeClip({id:crypto.randomUUID(),sessionId,blob:file,startedAt:Date.now(),durationMs:await audioDuration(file),imported:true,source:'import',originalName:file.name,type:'imported audio'});entry.sessionId=sessionId;persistEntries();sheet.close();renderJournal();toast('Audio recording saved on this device.')}catch(e){toast('The recording could not be stored: '+e.message)}};
}

function renderTrends(){
  const values=entries.slice(0,range).reverse(),stats=rhythmStats(values,prefs.goal);
  screen.innerHTML=head('Your rhythm.','Real patterns from your own nights.')+`<div class="segment" role="group" aria-label="Recent nights">${[7,30,90].map(n=>`<button data-range="${n}" class="${range===n?'selected':''}">${n} nights</button>`).join('')}</div>${!values.length?'<div class="empty"><span>☾</span><h3>One night at a time.</h3><p>Add your first night to see your personal trends.</p><button class="primary" id="trend-add">Add a night</button></div>':`<span class="kicker">AVERAGE TIME IN BED</span><div class="trend-value">${fmt(stats.average)}</div><div class="trend-sub">${values.length} most recent ${values.length===1?'night':'nights'}</div><div class="bars" aria-label="Time in bed for each night">${values.map(e=>`<div style="--height:${Math.max(2,Math.min(100,e.minutes/600*100))}%" title="${safe(e.date)} · ${fmt(e.minutes)}"></div>`).join('')}</div><div class="bar-days"><span>${safe(values[0].date)}</span><span>${safe(values.at(-1).date)}</span></div><div class="metrics"><div class="metric"><span>Nights at goal</span><strong>${stats.atGoal} / ${values.length}</strong></div><div class="metric"><span>Bedtime variation</span><strong>${stats.regularity===null?'—':stats.regularity+'m'}</strong></div><div class="metric"><span>Total time in bed</span><strong>${fmt(stats.total)}</strong></div><div class="metric"><span>Sleep goal</span><strong>${prefs.goal}h</strong></div></div><div class="insight"><div class="kicker">YOUR MORNING REFLECTIONS</div><h3>${values.filter(e=>e.mood==='Rested').length} rested mornings.</h3><p>Notice how your routines, notes, and recorded sound events line up with how you feel. Time in bed is not measured time asleep.</p></div><p class="note">Bedtime variation is the standard deviation of logged bedtimes. No sleep-stage, medical, or snoring score is calculated.</p>`}`;
  $$('[data-range]').forEach(b=>b.onclick=()=>{range=Number(b.dataset.range);renderTrends()});if($('#trend-add'))$('#trend-add').onclick=()=>nightForm();const comparisons=habitComparisons(values);screen.insertAdjacentHTML('beforeend',comparisons.length?'<div class="section"><span>Your habit comparisons</span></div>'+comparisons.map(c=>`<div class="habit-insight"><strong>${safe(c.factor)}</strong><p>${c.withCount} nights with this tag, ${c.withoutCount} without. You logged ${Math.abs(c.difference)} minutes ${c.difference>=0?'more':'less'} time in bed on tagged nights.</p><small>Association in your notes; not proof of cause or sleep quality.</small></div>`).join(''):'<p class="note">Tag your routines to unlock habit comparisons. At least three nights with and three without a tag are needed.</p>');
}

async function renderProfile(){
  const [t,p]=displayTime(prefs.wake);
  screen.innerHTML=head('Your sleep space.','Private, simple, and made for your nights.')+`<div class="avatar">☾</div><h2 class="profile-name">A little more you.</h2><div class="profile-sub">${entries.length} nights in your journal</div><span class="kicker">YOUR PREFERENCES</span><div class="group"><button class="setting" id="pref-wake"><span>☀ Wake-up alarm</span><small>${prefs.alarm?t+' '+p:'Off'} ›</small></button><button class="setting" id="pref-goal"><span>☾ Time-in-bed goal</span><small>${prefs.goal} hours ›</small></button><button class="setting" id="energy"><span>♧ Battery profile</span><small>${prefs.energy==='saver'?'Battery saver':'Balanced'} ›</small></button><button class="setting" id="pref-record"><span>♬ Night-sound recording</span><small>${prefs.record?'On':'Off'} ›</small></button><button class="setting" id="install"><span>＋ Install on Home Screen</span><small>${installed()?'Installed':'How to'} ›</small></button></div><span class="kicker">YOUR DEVICE, YOUR DATA</span><div class="group"><button class="setting" id="export"><span>Export journal as JSON</span><small>↓</small></button><button class="setting" id="csv"><span>Export journal as CSV</span><small>↓</small></button><button class="setting" id="import"><span>Restore a journal backup</span><small>↑</small></button><button class="setting" id="storage"><span>Device storage</span><small id="storage-value">Checking…</small></button><button class="setting" id="about"><span>Features & browser limits</span><small>›</small></button></div><p class="note">Recordings are saved in IndexedDB on this device.<br>Nothing you record is uploaded. Clearing site data removes it.<br>Download clips and export your journal to keep a backup.</p><p class="note" id="offline-state">${navigator.onLine?'Online':'Offline'} · ${installed()?'Home Screen app':'Browser app'}</p>`;
  $('#energy').onclick=energySheet;$('#pref-wake').onclick=wakeSheet;$('#pref-record').onclick=recordSheet;$('#install').onclick=installSheet;$('#pref-goal').onclick=()=>{modal(sh('Your space to rest.')+`<label for="goal">Time-in-bed goal</label><select id="goal">${[6,7,8,9,10].map(n=>`<option value="${n}" ${prefs.goal===n?'selected':''}>${n} hours</option>`).join('')}</select><button class="primary" id="goal-save">Save goal</button>`);$('#goal-save').onclick=()=>{prefs.goal=Number($('#goal').value);persistPrefs();sheet.close();renderProfile()}};
  $('#export').onclick=()=>download(new Blob([JSON.stringify({format:'sleep-studio-journal',version:1,exportedAt:new Date().toISOString(),prefs,entries},null,2)],{type:'application/json'}),'sleep-studio-journal.json');
  $('#csv').onclick=()=>{const q=v=>'"'+String(v??'').replaceAll('"','""')+'"',rows=[['Night','Bedtime','Wake-up','Minutes in bed','Mood','Factors','Reflection'],...entries.map(e=>[e.date,e.bed,e.wake,e.minutes,e.mood,(e.factors||[]).join('; '),e.note])];download(new Blob(['\uFEFF'+rows.map(r=>r.map(q).join(',')).join('\r\n')],{type:'text/csv'}),'sleep-studio-journal.csv')};$('#import').onclick=importJournal;
  $('#storage').onclick=async()=>{let text='Your browser manages storage. Export important recordings.';if(navigator.storage?.estimate){const e=await navigator.storage.estimate();text=`${Math.round((e.usage||0)/1024/1024)} MB used of approximately ${Math.round((e.quota||0)/1024/1024)} MB available.`}modal(sh('Your device storage.')+`<p class="sheet-copy">${text}</p><p class="sheet-copy">Audio clips are local to this origin and browser profile. Download individual clips from your journal. Exported JSON includes journal text and preferences, not audio files.</p><button class="primary" id="persist-storage">Request persistent storage</button>`);$('#persist-storage').onclick=async()=>{const ok=await navigator.storage?.persist?.();toast(ok?'Persistent storage granted.':'The browser decides storage retention. Keep backups.')}};
  $('#about').onclick=()=>modal(sh('Made for the Home Screen.')+'<p class="sheet-copy">Implemented: offline installation, local journal and trends, real microphone sound-event clips with playback and download, original wind-down sounds, timed sessions, an in-app wake alarm with snooze, and data export.</p><p class="sheet-copy">A microphone event means a louder sound, not automatically snoring, coughing, or sleep talking. This app does not measure sleep stages, sleep quality, or sleep apnea. Proprietary Sleep Cycle algorithms and paid content are not included.</p><p class="sheet-copy">iOS may stop browser capture in the background or when locked. Keep this app visible and the screen awake; interruptions are logged. Alarms need the open app. Set a backup in Clock.</p><p class="sheet-copy">Independent recreation inspired by <a href="https://sleepcycle.com/" target="_blank" rel="noopener">Sleep Cycle</a>.</p>');
  if(navigator.storage?.estimate){const est=await navigator.storage.estimate();if($('#storage-value'))$('#storage-value').textContent=Math.round((est.usage||0)/1024/1024)+' MB ›'}else if($('#storage-value'))$('#storage-value').textContent='On this device ›';
}
function importJournal(){modal(sh('Restore a journal backup.')+'<p class="sheet-copy">Choose a Sleep Studio JSON export. Entries merge by ID; existing nights are kept. Audio clips are not part of JSON backups.</p><label for="journal-import">Journal JSON</label><input type="file" id="journal-import" accept="application/json,.json"><button class="primary" id="restore">Restore journal</button>');$('#restore').onclick=async()=>{const file=$('#journal-import').files[0];if(!file||file.size>5*1024*1024){toast('Choose a JSON backup smaller than 5 MB.');return}try{const data=JSON.parse(await file.text()),incoming=Array.isArray(data)?data:data.entries;if(!Array.isArray(incoming)||incoming.some(e=>!/^\d{4}-\d{2}-\d{2}$/.test(e.date)||!Number.isFinite(e.minutes)||e.minutes<0||e.minutes>1440||typeof e.bed!=='string'||typeof e.wake!=='string'))throw new Error('Invalid journal backup.');const ids=new Set(entries.map(e=>e.id));let added=0;for(const e of incoming){const id=String(e.id||crypto.randomUUID());if(ids.has(id))continue;entries.push({id,date:e.date,bed:e.bed.slice(0,5),wake:e.wake.slice(0,5),minutes:e.minutes,mood:String(e.mood||'Not recorded').slice(0,50),note:String(e.note||'').slice(0,500),factors:Array.isArray(e.factors)?e.factors.map(String).slice(0,10):[]});ids.add(id);added++}entries.sort((a,b)=>b.date.localeCompare(a.date));persistEntries();sheet.close();renderProfile();toast(`${added} nights restored.`)}catch(e){toast(e.message||'Unable to read this backup.')}}}

function soundsSheet(){
  modal(sh('Find your quiet.')+`<div class="sound-tabs"><span class="tag">ORIGINAL OFFLINE SOUNDS</span></div><div class="sounds">${sounds.map(([id,icon,name,description])=>`<button class="sound ${sound===id?'active':''}" data-sound="${id}" aria-label="${name}" aria-pressed="${sound===id}"><span class="art">${icon}</span><span><strong>${name}</strong><small>${description}</small></span><span class="play">${sound===id?'Ⅱ':'▶'}</span></button>`).join('')}</div><label for="volume">Volume</label><input id="volume" type="range" min="0" max="1" step=".01" value="${prefs.volume}"><label for="sound-timer">Fade out after</label><select id="sound-timer">${[10,15,30,45,60,90,0].map(n=>`<option value="${n}" ${prefs.soundTimer===n?'selected':''}>${n?n+' minutes':'All night / until stopped'}</option>`).join('')}</select><button class="secondary" id="stop-sound">Stop all sounds</button><p class="note">Sound playback may continue when locked, depending on iOS and your audio settings. Recording and alarms still require the visible app.</p>`);
  $$('[data-sound]').forEach(b=>b.onclick=async()=>{if(sound===b.dataset.sound)stopSound();else await startSound(b.dataset.sound);soundsSheet();if(tab==='sleep')renderSleep()});$('#volume').oninput=e=>{prefs.volume=Number(e.target.value);if(soundAudio)soundAudio.volume=prefs.volume;persistPrefs()};$('#sound-timer').onchange=e=>{prefs.soundTimer=Number(e.target.value);persistPrefs();setSoundTimer()};$('#stop-sound').onclick=()=>{stopSound();soundsSheet();if(tab==='sleep')renderSleep()};
}
async function startSound(id){stopClipPlayback();stopSound();soundAudio=new Audio(new URL(`audio/${id}.wav`,import.meta.url));soundAudio.loop=true;soundAudio.volume=prefs.volume;try{await soundAudio.play();sound=id;setSoundTimer();if('mediaSession'in navigator){navigator.mediaSession.metadata=new MediaMetadata({title:sounds.find(s=>s[0]===id)[2],artist:'Sleep Studio',album:'Wind-down sounds',artwork:[{src:new URL('icons/icon-512.png',import.meta.url).href,sizes:'512x512',type:'image/png'}]});navigator.mediaSession.setActionHandler('pause',()=>{soundAudio?.pause()});navigator.mediaSession.setActionHandler('play',()=>{soundAudio?.play().catch(()=>{})});navigator.mediaSession.setActionHandler('stop',()=>{stopSound();if(tab==='sleep')renderSleep()})}}catch(e){stopSound();toast('Sound could not play. Open it again after the page finishes loading.') }}
function stopSound(){clearTimeout(soundTimer);clearInterval(stopSound.fade);if(soundAudio){soundAudio.pause();soundAudio.src='';soundAudio=null}sound='';if('mediaSession'in navigator)navigator.mediaSession.playbackState='none'}
function setSoundTimer(){clearTimeout(soundTimer);clearInterval(stopSound.fade);if(!sound||!prefs.soundTimer)return;soundTimer=setTimeout(()=>{const audio=soundAudio;if(!audio)return;let step=0;stopSound.fade=setInterval(()=>{if(soundAudio!==audio){clearInterval(stopSound.fade);return}audio.volume=Math.max(0,prefs.volume*(1-++step/20));if(step>=20){stopSound();if(tab==='sleep')renderSleep();if(sheet.open&&$('#stop-sound'))soundsSheet()}},500)},Math.max(0,prefs.soundTimer*60000-10000))}
async function playAlarm(preview=false){stopAlarm();alarmAudio=new Audio(new URL('audio/chime.wav',import.meta.url));alarmAudio.loop=!preview;alarmAudio.volume=preview?0.35:0.7;try{await alarmAudio.play()}catch{toast('Enable sound by tapping the chime preview before sleeping.')}if(preview)setTimeout(stopAlarm,3500)}
function stopAlarm(){if(alarmAudio){alarmAudio.pause();alarmAudio.src='';alarmAudio=null}}
function showAlarm(){ringing=true;document.body.classList.remove('night-mode');playAlarm();modal(sh('Good morning. ☀')+'<p class="sheet-copy">Your planned wake-up time is here. Take a moment to begin your day.</p><button class="primary" id="stop-alarm">Stop alarm</button><button class="secondary" id="snooze-alarm">Snooze '+prefs.snooze+' minutes</button>');$('#stop-alarm').onclick=()=>{stopAlarm();ringing=false;alarmDue=null;sheet.close()};$('#snooze-alarm').onclick=()=>{stopAlarm();ringing=false;alarmDue=Date.now()+prefs.snooze*60000;if(session){session.alarmDue=alarmDue;save('session',session)}sheet.close();toast('Snoozing for '+prefs.snooze+' minutes.')};}
function startSessionTicker(){if(sessionTimer)return;sessionTimer=setInterval(()=>{if(!session){clearInterval(sessionTimer);sessionTimer=null;return}if($('#elapsed'))$('#elapsed').textContent=elapsed();if(alarmDue&&!ringing&&Date.now()>=alarmDue){alarmDue=null;showAlarm()}},1000)}
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible'&&session&&prefs.keepAwake)requestWakeLock()});
window.addEventListener('pagehide',()=>{if(session){session.gaps=session.gaps||[];session.gaps.push({startedAt:Date.now(),reason:'App page hidden or closed'});save('session',session)}});

function installSheet(){modal(sh(installed()?'You’re on the Home Screen.':'Keep your nights close.')+(installed()?'<p class="sheet-copy">Sleep Studio is running as an installed web app. Your journal and clips stay on this device.</p>':'<ol class="install-steps"><li>Open this app’s link in <strong>Safari</strong> on your iPhone.</li><li>Tap <strong>Share</strong>, then <strong>Add to Home Screen</strong>.</li><li>Turn on <strong>Open as Web App</strong> if shown, then tap <strong>Add</strong>.</li><li>Launch Sleep Studio from its new icon.</li></ol><p class="sheet-copy">No Xcode, App Store, or GitHub app is needed. GitHub Pages can host the same installable files.</p>')+(deferredInstall?'<button class="primary" id="native-install">Install Sleep Studio</button>':'')+'<p class="note">After the first complete online load, the app and sound library are cached for offline use. Recordings stay local to this installed app’s storage.</p>');if($('#native-install'))$('#native-install').onclick=async()=>{await deferredInstall.prompt();deferredInstall=null;sheet.close()}}
window.addEventListener('beforeinstallprompt',event=>{event.preventDefault();deferredInstall=event});
window.addEventListener('appinstalled',()=>{toast('Sleep Studio is installed.');go(tab)});
window.addEventListener('online',()=>{if(tab==='profile')renderProfile()});window.addEventListener('offline',()=>toast('Offline mode. Your local journal and saved audio remain available.'));
if('serviceWorker'in navigator)navigator.serviceWorker.register(new URL('./sw.js',import.meta.url),{scope:'./'}).then(reg=>{reg.addEventListener('updatefound',()=>{const worker=reg.installing;worker?.addEventListener('statechange',()=>{if(worker.state==='installed'&&navigator.serviceWorker.controller)toast('An app update is ready. Finish your session, then reopen.')})})}).catch(()=>toast('Offline caching is unavailable here. Keep this page online.'));
document.body.classList.toggle('standalone',installed());
if(session){startSessionTicker();recStatus='paused';recError='Session restored. Microphone recording needs your tap to resume.';try{clipCount=(await listClips(session.id)).length}catch{}}
go('sleep');

async function labelClip(id){const clip=await getClip(id);if(!clip)return;modal(sh('What do you hear?')+`<p class="sheet-copy">This is your own label after listening, not an automatic detection.</p><label for="clip-label">Sound label</label><select id="clip-label">${['Unlabeled sound','Snoring','Sleep talking','Coughing','Breathing','Background noise','Other person','Other'].map(label=>`<option ${clip.userLabel===label?'selected':''}>${label}</option>`).join('')}</select><button class="primary" id="save-label">Save my label</button>`);$('#save-label').onclick=async()=>{await storeClip({...clip,userLabel:$('#clip-label').value});sheet.close();renderJournal()}}
function energySheet(){modal(sh('Lighter on your night.')+`<label for="energy-mode">Recording profile</label><select id="energy-mode"><option value="saver" ${prefs.energy==='saver'?'selected':''}>Battery saver</option><option value="balanced" ${prefs.energy==='balanced'?'selected':''}>Balanced</option></select><label for="clip-limit">Maximum clips per session</label><select id="clip-limit">${[50,100,200].map(n=>`<option value="${n}" ${prefs.clipLimit===n?'selected':''}>${n} short clips</option>`).join('')}</select><p class="sheet-copy">Battery saver checks sound twice per second, uses a smaller analysis buffer and requests lower-bitrate audio. Balanced checks five times per second. All clips are at most 10 seconds; recording stops at the cap or 25 MB per session.</p><p class="sheet-copy">No AI model downloads, continuous visual animation, cloud recording, or background polling when idle. Keeping the screen awake can still use significant battery. Browser/phone hardware may ignore requested audio rates.</p><button class="primary" id="save-energy">Save battery profile</button>`);$('#save-energy').onclick=()=>{prefs.energy=$('#energy-mode').value;prefs.clipLimit=Number($('#clip-limit').value);persistPrefs();sheet.close();renderProfile();toast('Profile saved for your next recording session.')}}
